};

class MenuEntry {
  unsigned int flags;
public:
  virtual ~MenuEntry();
};

class Submenu : public MenuEntry {};

class Menu {
  Menu *parent;
  int entries;
  MenuEntry **entry;
  int activeentry;
  bool isopen;
  char padding[3];
  Menu *closeto;
  void *control;
public:
  virtual ~Menu();
  void DelEntry(MenuEntry *entry);
};

template <class T>
class Node {
public:
  T *Obj;
  Node<T> *next;
  Node<T> *prev;
};

template <class T>
class List {
  Node<T> *head;
  Node<T> *tail;
public:
  void DestroyList(void) {
    Node<T>* node = head->next;
    while (node != tail)
    {
      Node<T>* temp = node->next;
      delete node->Obj;
      delete node;
      node = temp;
    }

    head->next = tail;
    tail->prev = head;
    head->prev = tail->next = 0;
  }
};

class camera_list {
public:
  Submenu *smenu;
  Menu *cam_menu;
  camera **camlist_start;
  List<camMenuObj> dbmenu_list;
private:
  int num_cams;
  char **names;
public:
  void DestroyCameraList(void);
};

extern Menu *menu_inner_camtool;

