void camera_list::DestroyCameraList(void)
{
	if (num_cams > 0)
	{
		for (int n = 0; n < num_cams; n++)
		{
			delete (camlist_start[n]);
			delete [] (names[n]);
		}

		delete[] camlist_start;
		delete[] names;
	}

	dbmenu_list.DestroyList();
	delete cam_menu;
	menu_inner_camtool->DelEntry(smenu);
	delete smenu;
	smenu = NULL;
	cam_menu = NULL;
}
